// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        // Admissible caller: neither the current owner (the test contract) nor address(0),
        // so the mutant's `msg.sender != address(0)` check passes but the reference's
        // `msg.sender == owner` check fails.
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.prank(actor);
        bool ok;
        try c.setOwner(actor) { ok = true; } catch { ok = false; }
        // Rule: a non-owner caller can never change the owner — setOwner must revert.
        assertTrue(!ok && c.owner() == address(this));
    }
}
